components.css:
.ds-preview { container-type:inline-size; aspect-ratio:16/9; position:relative; font-family:Manrope,sans-serif; color:#fff4fb; background:#0d0a13; }
.ds-card { min-width:0; min-height:0; position:relative; border:1px solid transparent; border-radius:1.65cqw; padding:.8cqw; background:linear-gradient(125deg,var(--glass),#130e1bea 68%) padding-box,linear-gradient(145deg,#ac59967d,#7b406b70) border-box; box-shadow:0 .35cqw 1.2cqw #0005,0 0 .65cqw #f573c014,inset 0 .35cqw 1.4cqw #ed65be16; }
.ds-rim-decoration { position:absolute; inset:-1px; pointer-events:none; border-radius:inherit; z-index:3; }
.ds-rim-light { --corner-light:radial-gradient(ellipse 38% 85% at 8% 0%,#ffbbe0 0%,#fb7dbf 24%,#e969bda8 43%,transparent 78%),radial-gradient(ellipse 22% 58% at 100% 100%,#ffe5ef 0%,#ff9cd0 20%,#ed71bfab 45%,transparent 88%); position:absolute; inset:0; border-radius:inherit; }
.ds-rim-light::before,.ds-rim-halo::before { content:''; position:absolute; inset:0; border-radius:inherit; background:var(--corner-light); padding:1.15px; mask:linear-gradient(#fff 0 0) content-box,linear-gradient(#fff 0 0); mask-composite:exclude; }
.ds-rim-halo { position:absolute; inset:0; border-radius:inherit; filter:blur(.36cqw); opacity:.95; }
.ds-rim-halo::before { padding:.42cqw; }
.ds-rim-hotspot { position:absolute; top:-.025cqw; left:8%; width:14%; height:.12cqw; background:linear-gradient(90deg,transparent,#ffb0da 18%,#fffaf4 38%,#fffaf4 57%,#ffc3e3 72%,transparent); filter:drop-shadow(0 0 .15cqw #ffe5f2) drop-shadow(0 0 .32cqw #ff7fcaa6); }
.ds-card h2 { margin:0; font-size:1.95cqw; font-weight:800; line-height:1.15; letter-spacing:-.025em; font-variant-numeric:tabular-nums; white-space:nowrap; }
.ds-card { --glass:rgba(46,23,48,.8); position:absolute; top:9cqw; left:3.5cqw; width:calc((93cqw - 4.6cqw)/3); height:calc((41.75cqw - 2.8cqw)/3); }
